'use strict';
let selectedPolitician=null;
const politicianPriceChecks=new Map();
function politicianRecords(person,records=signalData){const today=new Date().toISOString().slice(0,10);return records.filter(r=>r.person===person&&r.quality!=='User-provided'&&r.traded<=today&&disclosedDate(r)&&disclosedDate(r)<=today).sort((a,b)=>b.traded.localeCompare(a.traded)||(disclosedDate(b)||'').localeCompare(disclosedDate(a)||'')||String(a.id).localeCompare(String(b.id)))}
function politicianNames(){return [...new Set([...Object.keys(ROSTER),...signalData.map(r=>r.person)])].sort((a,b)=>a.localeCompare(b))}
function timelineReturn(r){const p=priceReturn(r.type==='Sale'?{...r,type:'Purchase'}:r),d=r.type==='Sale'?null:typeof followerReturn==='function'?followerReturn(r):null;const metric=(label,v)=>`<span>${label} <b class="${v?(v.pct>=0?'gain':'loss'):'muted'}">${v?percent(v):'—'}</b></span>`;return `<div class="timeline-returns">${metric(r.type==='Sale'?'Stock since sale':'Stock since '+(r.type==='Exercise'?'exercise':'buy'),p)}${r.type!=='Sale'?metric('Since disclosure',d):'<span class="muted">Realized profit unknown</span>'}</div><small class="muted">${p?`Close ${date(p.asOf)}${p.stale?' · stale':''}${p.underlying?' · underlying stock, not option return':''}`:'Comparable price unavailable'}${d?' · Disclosure entry '+date(d.basisDate):''}</small>`}
function politicianTimeline(rows){if(!rows.length)return '<p class="empty">No dated public transactions in the loaded history.</p>';let month='';return '<ol class="trade-timeline">'+rows.map(r=>{const m=r.traded.slice(0,7),heading=m!==month?`<li class="timeline-month">${new Date(r.traded+'T00:00:00Z').toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})}</li>`:'';month=m;return heading+`<li class="timeline-event ${r.type==='Sale'?'sale':r.type==='Purchase'?'purchase':'exercise'}"><span class="timeline-dot" aria-hidden="true"></span><article><div class="timeline-event-head"><time datetime="${esc(r.traded)}">${date(r.traded)}</time><strong class="timeline-action">${r.type==='Sale'?'Sold':r.type==='Purchase'?'Bought':'Exercised'}</strong><button class="ticker-link" data-ticker="${esc(r.ticker)}">${esc(r.ticker)}</button><b class="timeline-amount">${esc(r.amount)}</b></div><div class="timeline-company">${esc(r.company)} · ${esc(r.asset)}</div><div class="timeline-meta">Disclosed ${date(disclosedDate(r))} · ${esc(r.owner)}</div>${timelineReturn(r)}<div class="timeline-links"><button data-detail="${esc(r.id)}">Trade details</button>${/^https:\/\//.test(r.source)?`<a href="${esc(r.source)}" target="_blank" rel="noopener">Source filing ↗</a>`:''}</div></article></li>`}).join('')+'</ol><p class="timeline-end">Start of loaded history · earlier trades may be missing</p>'}
function renderPoliticianBrowser(){const q=$('#politicianSearch').value.trim().toLowerCase(),names=politicianNames(),matches=names.filter(n=>n.toLowerCase().includes(q));$('#politicianMatches').innerHTML=q?matches.map(n=>`<button class="${n===selectedPolitician?'primary':'secondary'}" data-profile="${esc(n)}" aria-pressed="${n===selectedPolitician}">${esc(n)}</button>`).join('')||'<p role="status">No matching politician in the loaded disclosures.</p>':'';$('#politicianDirectory').hidden=!!selectedPolitician||!!q;$('#politicianProfile').hidden=!selectedPolitician;if(!selectedPolitician){$('#politicianProfile').innerHTML='';return}const rows=politicianRecords(selectedPolitician),old=$('#politicianTimelineScroll')?.scrollTop||0,holdingsOpen=$('.profile-holdings')?.open||false;$('#politicianProfile').innerHTML=`<div class="profile-actions"><button class="primary" data-people-root="${esc(selectedPolitician)}">See research map →</button><span>${esc(selectedPolitician)} · ${esc(politicianTitle(selectedPolitician))}</span></div><div class="politician-detail-layout"><aside class="politician-summary">${card(selectedPolitician).replace(/(<section class="politician-portfolio"[\s\S]*?<\/section>)/,'<details class="profile-holdings"><summary>Portfolio & holdings</summary>$1</details>')}</aside><section class="politician-timeline-panel panel"><div class="timeline-heading"><h2>Trade timeline <small>${rows.length} transactions</small></h2><span><i class="legend-buy"></i> Buy <i class="legend-sale"></i> Sell <i class="legend-exercise"></i> Exercise</span></div><p class="timeline-note">Newest first · scroll down for older trades. Disclosure returns start at the first close after disclosure. Price changes are hypothetical; realized profit is unknown.</p><div id="politicianTimelineScroll" class="timeline-scroll" tabindex="0" aria-label="${esc(selectedPolitician)} trade timeline, newest first">${politicianTimeline(rows)}</div></section></div>`;$('#politicianTimelineScroll').scrollTop=old;$('.profile-holdings').open=holdingsOpen;}
function openPolitician(person){if(!politicianNames().includes(person))return;selectedPolitician=person;$('#politicianSearch').value=person;changeView('politicians');renderPoliticianBrowser();$('#politicianTimelineScroll').scrollTop=0;refreshPoliticianPrices(person);}
async function refreshPoliticianPrices(person){if(typeof ensurePoliticianRatingPrices==='function')ensurePoliticianRatingPrices([person]);if(typeof loadMarketPrices!=='function')return;const symbols=[...new Set(politicianRecords(person).map(r=>r.ticker))].filter(s=>/^[A-Z][A-Z0-9.-]{0,11}$/.test(s)&&(!politicianPriceChecks.has(s)||Date.now()-politicianPriceChecks.get(s)>15*60000));for(let i=0;i<symbols.length;i+=12){if(selectedPolitician!==person)break;const batch=symbols.slice(i,i+12);batch.forEach(s=>politicianPriceChecks.set(s,Date.now()));await loadMarketPrices(batch);if(selectedPolitician===person)renderPoliticianBrowser();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-profile]');if(b)openPolitician(b.dataset.profile)});
$('#politicianSearch').addEventListener('input',()=>{const q=$('#politicianSearch').value.trim().toLowerCase(),matches=politicianNames().filter(n=>n.toLowerCase().includes(q));const selected=matches.find(n=>n.toLowerCase()===q)||(q&&matches.length===1?matches[0]:null);selectedPolitician=selected||null;renderPoliticianBrowser();if(selected){$('#politicianTimelineScroll').scrollTop=0;refreshPoliticianPrices(selected)}});
$('#politicianBrowse').onclick=()=>{selectedPolitician=null;$('#politicianSearch').value='';renderPoliticianBrowser();$('#politicianSearch').focus()};
renderPoliticianBrowser();
